1262	static void gnss_ubx_cksum(const uint8_t *data, size_t n, uint8_t *cka,
1263	                           uint8_t *ckb)
1264	{
1265	  size_t i;
1266	  uint8_t a = 0;
1267	  uint8_t b = 0;
1268	
1269	  for (i = 0; i < n; i++) {
1270	    a = (uint8_t)(a + data[i]);
1271	    b = (uint8_t)(b + a);
1272	  }
1273	
1274	  *cka = a;
1275	  *ckb = b;
1276	}
