1730	static int gnss_ubx_send(int fd, uint8_t cls, uint8_t id,
1731	                         const uint8_t *payload, uint16_t plen)
1732	{
1733	  uint8_t cka;
1734	  uint8_t ckb;
1735	
1736	  if (plen > GNSS_EPH_INJECT_MAX) {
1737	    return -E2BIG;
1738	  }
1739	
1740	  s_ubx_tx[0] = 0xb5;
1741	  s_ubx_tx[1] = 0x62;
1742	  s_ubx_tx[2] = cls;
1743	  s_ubx_tx[3] = id;
1744	  s_ubx_tx[4] = (uint8_t)(plen & 0xff);
1745	  s_ubx_tx[5] = (uint8_t)((plen >> 8) & 0xff);
1746	  if (plen > 0 && payload != NULL) {
1747	    memcpy(s_ubx_tx + 6, payload, plen);
1748	  }
1749	
1750	  gnss_ubx_cksum(s_ubx_tx + 2, (size_t)plen + 4u, &cka, &ckb);
1751	  s_ubx_tx[6 + plen] = cka;
1752	  s_ubx_tx[7 + plen] = ckb;
1753	  return gnss_write_all(fd, s_ubx_tx, (int)plen + 8);
1754	}
