1756	static int gnss_ubx_send_pl(int fd, uint8_t cls, uint8_t id, uint16_t plen)
1757	{
1758	  uint8_t hdr[6];
1759	  uint8_t ck[2];
1760	  uint8_t cka;
1761	  uint8_t ckb;
1762	  uint16_t i;
1763	
1764	  if (plen > GNSS_UBX_PAY_MAX) {
1765	    return -E2BIG;
1766	  }
1767	
1768	  hdr[0] = 0xb5;
1769	  hdr[1] = 0x62;
1770	  hdr[2] = cls;
1771	  hdr[3] = id;
1772	  hdr[4] = (uint8_t)(plen & 0xff);
1773	  hdr[5] = (uint8_t)((plen >> 8) & 0xff);
1774	  gnss_ubx_cksum(hdr + 2, 4, &cka, &ckb);
1775	  for (i = 0; i < plen; i++) {
1776	    cka = (uint8_t)(cka + s_ubx_pl[i]);
1777	    ckb = (uint8_t)(ckb + cka);
1778	  }
1779	
1780	  ck[0] = cka;
1781	  ck[1] = ckb;
1782	  if (gnss_write_all(fd, hdr, 6) < 0) {
1783	    return -EIO;
1784	  }
1785	
1786	  if (plen > 0 && gnss_write_all(fd, s_ubx_pl, plen) < 0) {
1787	    return -EIO;
1788	  }
1789	
1790	  return gnss_write_all(fd, ck, 2);
1791	}
