1793	static int gnss_ubx_read_frame(int fd, uint8_t *cls, uint8_t *id,
1794	                               uint16_t *plen, int timeout_ms)
1795	{
1796	  enum {
1797	    ST_B5 = 0,
1798	    ST_62,
1799	    ST_CLS,
1800	    ST_ID,
1801	    ST_L1,
1802	    ST_L2,
1803	    ST_PAY,
1804	    ST_CKA,
1805	    ST_CKB,
1806	    ST_NMEA
1807	  };
1808	  int st = ST_B5;
1809	  uint8_t cka = 0;
1810	  uint8_t ckb = 0;
1811	  uint8_t got_cka = 0;
1812	  uint16_t len = 0;
1813	  uint16_t idx = 0;
1814	  uint32_t start = gnss_now_ms();
1815	
1816	  if (!gnss_ubx_pl_ensure()) {
1817	    return 0;
1818	  }
1819	
1820	  while (gnss_elapsed_ms(gnss_now_ms(), start) < (uint32_t)timeout_ms) {
1821	    char ch;
1822	    int ret;
1823	    uint32_t used = gnss_elapsed_ms(gnss_now_ms(), start);
1824	    int slice;
1825	
1826	    if (used >= (uint32_t)timeout_ms) {
1827	      break;
1828	    }
1829	
1830	    slice = (int)((uint32_t)timeout_ms - used);
1831	
1832	    if (slice < 1) {
1833	      break;
1834	    }
1835	
1836	    if (slice > 200) {
1837	      slice = 200;
1838	    }
1839	
1840	    ret = gnss_read_byte(fd, &ch, slice);
1841	    if (ret < 0) {
1842	      return ret;
1843	    }
1844	
1845	    if (ret == 0) {
1846	      continue;
1847	    }
1848	
1849	    switch (st) {
1850	      case ST_B5:
1851	        if ((uint8_t)ch == 0xb5) {
1852	          st = ST_62;
1853	        } else if (ch == '$') {
1854	          st = ST_NMEA;
1855	        }
1856	        break;
1857	
1858	      case ST_62:
1859	        st = ((uint8_t)ch == 0x62) ? ST_CLS : ST_B5;
1860	        break;
1861	
1862	      case ST_CLS:
1863	        *cls = (uint8_t)ch;
1864	        cka = *cls;
1865	        ckb = cka;
1866	        st = ST_ID;
1867	        break;
1868	
1869	      case ST_ID:
1870	        *id = (uint8_t)ch;
1871	        cka = (uint8_t)(cka + *id);
1872	        ckb = (uint8_t)(ckb + cka);
1873	        st = ST_L1;
1874	        break;
1875	
1876	      case ST_L1:
1877	        len = (uint8_t)ch;
1878	        cka = (uint8_t)(cka + (uint8_t)ch);
1879	        ckb = (uint8_t)(ckb + cka);
1880	        st = ST_L2;
1881	        break;
1882	
1883	      case ST_L2:
1884	        len |= ((uint16_t)(uint8_t)ch) << 8;
1885	        cka = (uint8_t)(cka + (uint8_t)ch);
1886	        ckb = (uint8_t)(ckb + cka);
1887	        if (len > GNSS_UBX_PAY_MAX) {
1888	          st = ST_B5;
1889	          break;
1890	        }
1891	
1892	        idx = 0;
1893	        st = (len == 0) ? ST_CKA : ST_PAY;
1894	        break;
1895	
1896	      case ST_PAY:
1897	        s_ubx_pl[idx] = (uint8_t)ch;
1898	        cka = (uint8_t)(cka + (uint8_t)ch);
1899	        ckb = (uint8_t)(ckb + cka);
1900	        idx++;
1901	        if (idx >= len) {
1902	          st = ST_CKA;
1903	        }
1904	        break;
1905	
1906	      case ST_CKA:
1907	        got_cka = (uint8_t)ch;
1908	        st = ST_CKB;
1909	        break;
1910	
1911	      case ST_CKB:
1912	        if (got_cka == cka && (uint8_t)ch == ckb) {
1913	          *plen = len;
1914	          return 1;
1915	        }
1916	
1917	        st = ST_B5;
1918	        break;
1919	
1920	      case ST_NMEA:
1921	        if (ch == '\n') {
1922	          st = ST_B5;
1923	        }
1924	        break;
1925	
1926	      default:
1927	        st = ST_B5;
1928	        break;
1929	    }
1930	  }
1931	
1932	  return 0;
1933	}
