1935	/* UBX-CFG-VALSET RAM：等 ACK/NAK。NMEA 会被 read_frame 丢掉。 */
1936	static int gnss_ubx_wait_ack(int fd, uint8_t want_cls, uint8_t want_id,
1937	                              int timeout_ms)
1938	{
1939	  uint32_t start = gnss_now_ms();
1940	
1941	  while (gnss_elapsed_ms(gnss_now_ms(), start) < (uint32_t)timeout_ms) {
1942	    uint8_t cls;
1943	    uint8_t id;
1944	    uint16_t plen;
1945	    int ret;
1946	
1947	    ret = gnss_ubx_read_frame(fd, &cls, &id, &plen, 80);
1948	    if (ret <= 0) {
1949	      continue;
1950	    }
1951	
1952	    if (cls == 0x05 && plen >= 2 &&
1953	        s_ubx_pl[0] == want_cls && s_ubx_pl[1] == want_id) {
1954	      return (id == 0x01) ? 1 : -1;
1955	    }
1956	  }
1957	
1958	  return 0;
1959	}
