1961	static int gnss_cfg_valset_u1(int fd, uint32_t key, uint8_t val)
1962	{
1963	  uint8_t pl[9];
1964	
1965	  pl[0] = 0x00;
1966	  pl[1] = 0x01;
1967	  pl[2] = 0x00;
1968	  pl[3] = 0x00;
1969	  pl[4] = (uint8_t)key;
1970	  pl[5] = (uint8_t)(key >> 8);
1971	  pl[6] = (uint8_t)(key >> 16);
1972	  pl[7] = (uint8_t)(key >> 24);
1973	  pl[8] = val;
1974	  gnss_drain(fd);
1975	  if (gnss_ubx_send(fd, 0x06, 0x8a, pl, sizeof(pl)) < 0) {
1976	    return -1;
1977	  }
1978	
1979	  return gnss_ubx_wait_ack(fd, 0x06, 0x8a, 250);
1980	}
