1994	static void gnss_dyn_apply(int fd, bool force)
1995	{
1996	  uint8_t want;
1997	  uint32_t now;
1998	  int rc;
1999	
2000	  if (fd < 0 || g_eph_busy || g_dbd_run || !g_link_got_nmea) {
2001	    return;
2002	  }
2003	
2004	  now = gnss_now_ms();
2005	  if (gnss_eph_grace_locked(now)) {
2006	    return;
2007	  }
2008	
2009	  want = gnss_dyn_want();
2010	  if (want != g_dyn_try_want) {
2011	    g_dyn_try_want = want;
2012	    g_dyn_fails = 0;
2013	  }
2014	
2015	  if (!force && g_dyn_have == want) {
2016	    return;
2017	  }
2018	
2019	  if (!force && g_dyn_fails >= GNSS_DYN_FAIL_MAX) {
2020	    return;
2021	  }
2022	
2023	  if (!force && g_dyn_try_ms != 0
2024	      && gnss_elapsed_ms(now, g_dyn_try_ms) < GNSS_DYN_RETRY_MS) {
2025	    return;
2026	  }
2027	
2028	  g_dyn_try_ms = now;
2029	  rc = gnss_cfg_valset_u1(fd, GNSS_CFG_DYNMODEL, want);
2030	  if (rc > 0) {
2031	    g_dyn_have = want;
2032	    g_dyn_fails = 0;
2033	    syslog(LOG_INFO, "gnss: dynmodel %s\n", gnss_dyn_name(want));
2034	  } else {
2035	    g_dyn_fails++;
2036	    /* rc 区分两种完全不同的原因，别混在一起报：
2037	     *   -1 = 模组明确回 NAK（CFG-ACK id=0x00）→ 这个 dynModel 值它不支持；
2038	     *    0 = 250 ms 内没等到 ACK           → 是时序/丢帧问题，不是不支持。
2039	     * `dynmodel bike failed` 之前一直是这个笼统的报法，查不出是哪种。 */
2040	    syslog(LOG_WARNING, "gnss: dynmodel %s failed (%u/%u) rc=%d%s\n",
2041	           gnss_dyn_name(want), (unsigned)g_dyn_fails,
2042	           (unsigned)GNSS_DYN_FAIL_MAX, rc,
2043	           rc == -1 ? " (NAK: 值不支持)" :
2044	           rc == 0  ? " (超时: 没等到 ACK)" : "");
2045	
2046	    /* 明确 NAK = 这颗模组不支持这个值，**再试多少次都一样**。
2047	     *
2048	     * 现场就是 `dynmodel bike failed (1/3)(2/3)(3/3) rc=-1 (NAK: 值不支持)`：
2049	     * 每次开机白试 3 轮（3 次 CFG-VALSET + 等 ACK）。直接把计数拉满，
2050	     * 让它走"已放弃"那条路 —— 与超时（rc==0，值得重试）区分开。 */
2051	    if (rc == -1)
2052	      {
2053	        g_dyn_fails = GNSS_DYN_FAIL_MAX;
2054	      }
2055	  }
2056	}
