419	/**
420	 * @brief 手机 TIME_SYNC：写 CLOCK_REALTIME（CONFIG_RTC 时同步硬件 RTC）并可选改时区。
421	 *
422	 * 不在 Control 锁内执行：settimeofday / persist 可能阻塞。
423	 */
424	static void companion_apply_time_sync(const uint8_t *value, uint16_t length)
425	{
426	  uint32_t utc;
427	  int16_t tz_min = 0;
428	  bool have_tz = false;
429	  struct timespec now;
430	  struct timeval tv;
431	  long long delta;
432	
433	  if (value == NULL || length < COMPANION_CTRL_TIME_SYNC_MIN_LEN)
434	    {
435	      return;
436	    }
437	
438	  utc = (uint32_t)value[1]
439	        | ((uint32_t)value[2] << 8)
440	        | ((uint32_t)value[3] << 16)
441	        | ((uint32_t)value[4] << 24);
442	  if (utc < COMPANION_TIME_MIN_UNIX || utc > COMPANION_TIME_MAX_UNIX)
443	    {
444	      LOGI("TIME_SYNC reject utc=%lu", (unsigned long)utc);
445	      return;
446	    }
447	
448	  if (length >= COMPANION_CTRL_TIME_SYNC_LEN)
449	    {
450	      tz_min = (int16_t)((uint16_t)value[5] | ((uint16_t)value[6] << 8));
451	      if (tz_min >= MYVENDOR_DEVCTL_TZ_MIN && tz_min <= MYVENDOR_DEVCTL_TZ_MAX)
452	        {
453	          have_tz = true;
454	        }
455	    }
456	
457	  if (clock_gettime(CLOCK_REALTIME, &now) != 0)
458	    {
459	      now.tv_sec = 0;
460	    }
461	
462	  delta = (long long)now.tv_sec - (long long)utc;
463	  if (delta < 0)
464	    {
465	      delta = -delta;
466	    }
467	
468	  if (now.tv_sec < (time_t)COMPANION_TIME_MIN_UNIX || delta >= 2)
469	    {
470	      tv.tv_sec = (time_t)utc;
471	      tv.tv_usec = 0;
472	      if (settimeofday(&tv, NULL) != 0)
473	        {
474	          syslog(LOG_WARNING, "ble_companion: TIME_SYNC settimeofday errno=%d\n",
475	                 errno);
476	        }
477	      else
478	        {
479	          LOGI("RTC sync utc=%lu tz=%d",
480	               (unsigned long)utc, have_tz ? (int)tz_min : (int)myvendor_devctl_tz_min_get());
481	        }
482	    }
483	
484	  if (have_tz && tz_min != myvendor_devctl_tz_min_get())
485	    {
486	      (void)myvendor_devctl_tz_min_set(tz_min);
487	    }
488	}
