581	 */
582	static uint16_t gnss_on_write(gatts_handle_t srv_handle, bt_address_t *addr,
583	                              uint16_t attr_handle, const uint8_t *value,
584	                              uint16_t length, uint16_t offset)
585	{
586	  struct companion_gnss_fix fix;
587	  uint32_t count;
588	
589	  (void)srv_handle;
590	  (void)attr_handle;
591	  (void)offset;
592	
593	  if (!companion_is_phone(addr))
594	    {
595	      return length;
596	    }
597	
598	  if (length < COMPANION_GNSS_FIX_LEN)
599	    {
600	      LOGD("gnss write too short: %u", length);
601	      return length;
602	    }
603	
604	  gnss_fix_unpack(value, &fix);
605	  companion_bridge_gnss_set(&fix, mono_ms());
606	
607	  pthread_mutex_lock(&g_ctx.lock);
608	  g_ctx.last_fix     = fix;
609	  g_ctx.fix_valid    = fix.fix_quality != COMPANION_FIX_NONE;
610	  g_ctx.last_gnss_ms = mono_ms();
611	  count = ++g_ctx.status.gnss_rx_count;
612	
613	  if (g_ctx.fix_valid)
614	    {
615	      status_set_flags(COMPANION_STATUS_GPS_PHONE, 0);
616	    }
617	
618	  pthread_mutex_unlock(&g_ctx.lock);
619	
620	  LOGD("gnss #%lu lat=%ld lon=%ld q=%u sats=%u",
621	       (unsigned long)count, (long)fix.lat_e7, (long)fix.lon_e7,
622	       fix.fix_quality, fix.satellites);
623	  (void)count;  /* only read by LOGD, which is compiled out by default */
624	
625	  return length;
626	}
