            lv_snprintf(sub, sizeof(sub), "下次 %s", next_hm);
        }
    }

    helm_row_set(m, (*n)++, HELM_ICO_GPS, "星历", sub, val,
                 ACT_ENTER_EPH, HELM_KIND_GO);
}

